class _PillIconButton extends StatefulWidget {
  final String tooltip;
  final IconData icon;
  final Future<void> Function() onTap;
  final bool animate;

  const _PillIconButton({
    required this.tooltip,
    required this.icon,
    required this.onTap,
    this.animate = false,
  });

  @override
  State<_PillIconButton> createState() => _PillIconButtonState();
}

class _PillIconButtonState extends State<_PillIconButton> {
  bool _pressed = false;
  bool _busy = false;

  @override
  Widget build(BuildContext context) {
    final cs = Theme.of(context).colorScheme;
    final isHeart =
        widget.icon == Icons.favorite || widget.icon == Icons.favorite_border;
    final scale = widget.animate ? (_pressed ? 0.93 : 1.0) : 1.0;
    final opacity = widget.animate ? (_pressed ? 0.92 : 1.0) : 1.0;

    return Tooltip(
      message: widget.tooltip,
      child: InkWell(
        borderRadius: BorderRadius.circular(999),
        onTap: _busy
            ? null
            : () async {
                setState(() => _busy = true);
                try {
                  if (widget.animate) {
                    HapticFeedback.lightImpact();
                    setState(() => _pressed = true);
                    await Future.delayed(const Duration(milliseconds: 70));
                    if (mounted) setState(() => _pressed = false);
                  } else {
                    HapticFeedback.selectionClick();
                  }
                  await widget.onTap();
                } finally {
                  if (mounted) setState(() => _busy = false);
                }
              },
        onTapDown: (_) {
          if (!widget.animate) return;
          setState(() => _pressed = true);
        },
        onTapCancel: () {
          if (!widget.animate) return;
          setState(() => _pressed = false);
        },
        onTapUp: (_) {
          if (!widget.animate) return;
          setState(() => _pressed = false);
        },
        child: AnimatedScale(
          duration: const Duration(milliseconds: 120),
          curve: Curves.easeOut,
          scale: scale,
          child: AnimatedOpacity(
            duration: const Duration(milliseconds: 120),
            curve: Curves.easeOut,
            opacity: opacity,
            child: SizedBox(
              width: 44,
              height: 44,
              child: Icon(widget.icon,
                  size: 20,
                  color: isHeart ? cs.primary : cs.onSurface),
            ),
          ),
        ),
      ),
    );
  }
}

