class _AttractionDetailScreenState
    extends State<_AttractionDetailScreen> {
  TextEditingController? _myWaitCtrl;
  double _rating = 4.5;
  bool _showTranslated = false;
  final WaitAlertService _waitAlertService = WaitAlertService();

  @override
  void initState() {
    super.initState();
    try { _myWaitCtrl = TextEditingController(); } catch (_) {}
    WidgetsBinding.instance.addPostFrameCallback((_) async {
      try {
        if (!mounted) return;
        final app = context.read<AppState>();
        await app.ensureLoadedForAttraction(widget.attraction.id);
        final r = app.ratingForAttraction(widget.attraction.id) ?? widget.attraction.rating;
        final myWait = app.myWaitFor(widget.attraction.id);
        if (!mounted) return;
        setState(() {
          _rating = r;
          _myWaitCtrl?.text = myWait?.toString() ?? '';
        });
      } catch (_) {}
    });
  }

  @override
  void dispose() {
    _myWaitCtrl?.dispose();
    super.dispose();
  }

  Widget _buildWaitAlertBell(BuildContext context, Attraction a) {
    return StreamBuilder<bool>(
      stream: _waitAlertService.isAlertActiveFor(
        parkId: widget.parkId,
        attractionId: a.id,
      ),
      builder: (context, snap) {
        final active = snap.data ?? false;
        return _PillIconButton(
          tooltip: active ? 'Wait alert set' : 'Set wait time alert',
          icon: active ? Icons.notifications_active : Icons.notifications_none,
          onTap: () => _handleAlertTap(context, a, active),
        );
      },
    );
  }

  Future<void> _handleAlertTap(BuildContext context, Attraction a, bool active) async {
    final app = context.read<AppState>();
    if (app.currentUser == null) {
      Navigator.of(context).pushNamed('/signin');
      return;
    }
    if (active) {
      await _waitAlertService.clearAlert();
      return;
    }
    await _showThresholdSheet(context, a);
  }

  Future<void> _showThresholdSheet(BuildContext context, Attraction a) async {
    final options = [10, 15, 20, 30, 45];
    final selected = await showModalBottomSheet<int>(
      context: context,
      backgroundColor: Colors.white,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(20)),
      ),
      builder: (ctx) => SafeArea(
        child: Padding(
          padding: const EdgeInsets.all(20),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text('Notify me when wait drops below',
                  style: Theme.of(ctx).textTheme.titleMedium),
              const SizedBox(height: 16),
              Wrap(
                spacing: 10,
                runSpacing: 10,
                children: options
                    .map((m) => ActionChip(
                          label: Text('$m min'),
                          onPressed: () => Navigator.of(ctx).pop(m),
                        ))
                    .toList(),
              ),
            ],
          ),
        ),
      ),
    );
    if (selected == null) return;
    final ok = await _waitAlertService.setAlert(
      parkId: widget.parkId,
      attractionId: a.id,
      attractionName: a.name,
      thresholdMinutes: selected,
    );
    if (!ok && mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
            content: Text('Could not set alert. Check notification permissions.')),
      );
    }
  }

  @override
  Widget build(BuildContext context) {
    final loc = AppLocalizations.of(context) ?? AppLocalizations.of(context)!;
    final a = widget.attraction;
    final lookup = _I18nLookup(widget.i18n);
    final descPair = lookup.pairFromSectionIdField(context,
        section: 'attractions', id: a.id, field: 'desc', fallbackEn: a.description);
    final cat = widget.categoryLabel(a.category);
    final factLines = <String>[
      if (a.speedKmh != null) '${loc.speed}: ${a.speedKmh} km/h',
      if (a.heightM != null) '${loc.height}: ${a.heightM!.toStringAsFixed(0)} m',
      if (a.inversions != null) '${loc.inversions}: ${a.inversions}',
      if (a.openedYear != null) '${loc.opened}: ${a.openedYear}',
      if ((a.minHeightCm ?? 0) > 0) 'Min. height: ${a.minHeightCm} cm',
    ];
    return Scaffold(
      backgroundColor: Colors.white,
      appBar: AppBar(
        backgroundColor: Colors.white,
        title: Text(a.name),
        actions: [
          IconButton(
            tooltip: loc.share,
            icon: const Icon(Icons.share),
            onPressed: () => Share.share('${a.name} - Funparks'),
          ),
        ],
      ),
      body: Material(color: Colors.white, child: ListView(
        children: [
          AspectRatio(
            aspectRatio: 16 / 9,
            child: ParkImage(image: a.image, fit: BoxFit.cover, cacheWidth: 1200),
          ),
          Padding(
            padding: const EdgeInsets.fromLTRB(16, 14, 16, 20),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(_showTranslated ? descPair.translated : descPair.english,
                    style: Theme.of(context).textTheme.bodyMedium),
                TextButton(
                  onPressed: () => setState(() => _showTranslated = !_showTranslated),
                  child: Text(_showTranslated ? 'EN' : 'Translate'),
                ),
                const SizedBox(height: 10),
                Wrap(spacing: 8, runSpacing: 8, children: [
                  _Pill(icon: Icons.category, text: cat),
                  if (a.minHeightCm != null)
                    _Pill(icon: Icons.height, text: '${a.minHeightCm} cm+'),
                  _Pill(icon: Icons.timer, text: '${a.liveWaitMinutes} min (${loc.liveWait})'),
                    _buildWaitAlertBell(context, a),
                ]),
                const SizedBox(height: 14),
                _TextCard(title: 'Facts', lines: factLines),
                const SizedBox(height: 16),
                Row(children: [
                  Expanded(
                    child: FilledButton.icon(
                      onPressed: () => widget.onDirections(a),
                      icon: const Icon(Icons.directions),
                      label: Text(loc.directions),
                    ),
                  ),
                  const SizedBox(width: 12),
                  Expanded(
                    child: Consumer<AppState>(
                      builder: (_, app, __) {
                        final inMyDay = app.isInMyDayUnified(a.id);
                        return FilledButton.icon(
                          onPressed: () async {
                            HapticFeedback.lightImpact();
                            if (inMyDay) {
                              await app.removeFromMyDay(a.id);
                            } else {
                              await app.addToMyDay(MyDayItem(
                                id: a.id, name: a.name,
                                type: MyDayItemType.attraction,
                                estimatedMinutes: MyDayItem.defaultMinutes(MyDayItemType.attraction),
                              ));
                            }
                          },
                          icon: Icon(inMyDay ? Icons.favorite : Icons.favorite_border),
                          label: Text(inMyDay ? loc.removeFromMyDay : loc.addToMyDay),
                        );
                      },
                    ),
                  ),
                ]),
                const SizedBox(height: 18),
                Text(loc.myWaitTimeOptional, style: Theme.of(context).textTheme.titleMedium),
                const SizedBox(height: 8),
                TextField(
                  controller: _myWaitCtrl,
                  keyboardType: TextInputType.number,
                  decoration: InputDecoration(
                    hintText: loc.minutesHint,
                    border: OutlineInputBorder(borderRadius: BorderRadius.circular(12)),
                  ),
                ),
                const SizedBox(height: 10),
                SizedBox(
                  width: double.infinity,
                  child: FilledButton(
                    onPressed: () async {
                      try {
                        final app = context.read<AppState>();
                        final wait = int.tryParse(_myWaitCtrl?.text.trim() ?? '');
                        if (wait != null) await app.setMyWaitMinutes(a.id, wait);
                        if (!mounted) return;
                        ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(loc.saved)));
                      } catch (_) {}
                    },
                    child: Text(loc.save),
                  ),
                ),
                const SizedBox(height: 24),
                SizedBox(
                  width: double.infinity,
                  child: Consumer<AppState>(
                    builder: (_, app, __) => app.isLoggedIn
                      ? OutlinedButton.icon(
                          onPressed: () => _showReviewDialog(context),
                          icon: const Icon(Icons.rate_review_outlined),
                          label: const Text('Write a review'),
                        )
                      : OutlinedButton.icon(
                          onPressed: () => Navigator.of(context).pushNamed('/signin', arguments: 'register'),
                          icon: const Icon(Icons.rate_review_outlined),
                          label: const Text('Log in or Register to write a review'),
                        ),
                  ),
                ),
              ],
            ),
          ),
        ],
      )),
    );
  }
}
void _showReviewDialog(BuildContext context) {
  final textCtrl = TextEditingController();
  double rating = 4.5;
  showDialog(
    context: context,
    builder: (ctx) => StatefulBuilder(
      builder: (ctx, setS) => AlertDialog(
        title: const Text('Write a Review'),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Row(
              mainAxisAlignment: MainAxisAlignment.center,
              children: List.generate(5, (i) => IconButton(
                icon: Icon(i < rating.round() ? Icons.star : Icons.star_border, color: Colors.amber),
                onPressed: () => setS(() => rating = (i+1).toDouble()),
              )),
            ),
            TextField(
              controller: textCtrl,
              maxLines: 3,
              decoration: const InputDecoration(
                hintText: 'Share your experience...',
                border: OutlineInputBorder(),
              ),
            ),
          ],
        ),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('Cancel')),
          FilledButton(
            onPressed: () async {
              Navigator.pop(ctx);
              ScaffoldMessenger.of(context).showSnackBar(
                const SnackBar(content: Text('Review submitted! Thank you.')));
            },
            child: const Text('Submit'),
          ),
        ],
      ),
    ),
  );
}

